fn motion_primitives(window: &mut Window, cx: &mut App) -> AnyElement {
    if !cx.has_global::<SceneMotionPrimitives>() {
        cx.set_global(SceneMotionPrimitives::new(cx.theme()));
    }
    let now = cx.background_executor().now();
    let theme = cx.theme().clone();
    let selected = cx.global::<SceneMotionPrimitives>().demo;
    let tabs = Tabs::new("scene.motion.tabs")
        .tabs([
            TabItem::new("sliding-time", "Sliding time"),
            TabItem::new("spring", "Spring"),
            TabItem::new("keyframes", "Keyframes"),
            TabItem::new("presence", "Presence"),
            TabItem::new("stagger", "Stagger"),
        ])
        .selected(selected.id())
        .on_select(|id, _, cx| {
            let Some(demo) = MotionDemo::from_id(id.as_ref()) else {
                return;
            };
            let theme = cx.theme().clone();
            cx.update_global::<SceneMotionPrimitives, ()>(|scene, _| scene.select(demo, &theme));
            cx.refresh_windows();
        });

    let body = cx.update_global::<SceneMotionPrimitives, AnyElement>(|scene, cx| {
        scene.update_clock(now);
        if scene.clock_playing {
            window.request_animation_frame();
        }
        match scene.demo {
            MotionDemo::SlidingTime => scene.sliding_time(&theme, window, cx),
            MotionDemo::Spring => scene.spring(&theme, window, cx),
            MotionDemo::Keyframes => scene.keyframes(&theme, window, cx),
            MotionDemo::Presence => scene.presence(&theme, window, cx),
            MotionDemo::Stagger => scene.stagger(&theme, window, cx),
        }
    });

    stack(&theme)
        .w(px(640.0))
        .child(tabs)
        .child(body)
        .into_any_element()
}

fn animated_number(_window: &mut Window, cx: &mut App) -> AnyElement {
    if !cx.has_global::<SceneCounts>() {
        cx.set_global(SceneCounts {
            runs: 1204.0,
            seconds: 18.4,
        });
    }
    let counts = cx.global::<SceneCounts>();
    let (runs, seconds) = (counts.runs, counts.seconds);
    let theme = cx.theme().clone();

    // A readout is a reading, so it is drawn as one: the same card, caption
    // and hierarchy a KPI gets. A number floating on the canvas beside its
    // label is a debug print of the value, not a report of it.
    let readout = |label: &'static str, detail: &'static str, number: AnimatedNumber| {
        div()
            .column()
            .flex_1()
            .min_w_0()
            .gap(px(theme.space(Space::Xs)))
            .p(px(theme.space(Space::Md)))
            .card_surface(&theme, CardVariant::Filled)
            .child(
                crate::foundation::text(&theme, TypeScale::Caption, label)
                    .text_tone(&theme, TextTone::Muted),
            )
            .child(number)
            .child(
                crate::foundation::text(&theme, TypeScale::Caption, detail)
                    .text_tone(&theme, TextTone::Faint),
            )
    };

    stack(&theme)
        .w(px(520.0))
        .child(caption(
            &theme,
            "the published value is the target, from the frame it changes",
        ))
        .child(
            div()
                .row()
                .items_stretch()
                .w_full()
                .gap(px(theme.space(Space::Md)))
                .child(readout(
                    "Runs this week",
                    "counted by the host",
                    AnimatedNumber::new("scene.number.runs", runs)
                        .format(grouped)
                        .type_scale(TypeScale::Title),
                ))
                .child(readout(
                    "Median duration",
                    "one decimal, the host's choice",
                    AnimatedNumber::new("scene.number.seconds", seconds)
                        .format(|value| format!("{value:.1}s"))
                        .type_scale(TypeScale::Title),
                )),
        )
        .child(
            div().row().child(
                Button::new("scene.number.recount")
                    .label("Recount")
                    .on_click(|_, cx| {
                        cx.update_global::<SceneCounts, ()>(|counts, _| {
                            counts.runs += 318.0;
                            counts.seconds += 4.7;
                        });
                        cx.refresh_windows();
                    }),
            ),
        )
        .into_any_element()
}

fn drag_list(_window: &mut Window, cx: &mut App) -> AnyElement {
    let theme = cx.theme().clone();
    let carried = fixture_record(4);
    let anchor = fixture_record(1);
    // A capture cannot photograph a gesture, so the drag is placed by hand.
    // Staging fixes the ghost, the indicator, and the open slot, and takes the
    // pointer and the spring out of the picture.
    dnd::stage(
        StagedDrag::new(DragItem::new(
            "scene.drag.records",
            carried.0.clone(),
            carried.1.clone(),
        ))
        .landing(
            "scene.drag.records",
            DropPosition::Before(anchor.0.clone()),
            Some(1),
            true,
        ),
        cx,
    );

    stack(&theme)
        .w(px(420.0))
        .child(caption(
            &theme,
            SharedString::from(format!("{} moving before {}", carried.1, anchor.1)),
        ))
        .child(
            div()
                .relative()
                .child(
                    div()
                        .surface(&theme, Surface::Panel)
                        .radius(&theme, Radius::Card)
                        .py_token(&theme, Space::Xs)
                        .overflow_hidden()
                        .child(
                            List::new("scene.drag.records", 6, |index, _, _| {
                                let (id, label) = fixture_record(index);
                                ListItem::new(id, label.clone()).text(label)
                            })
                            // A row slides without its layout slot moving, so the
                            // viewport is one row taller than the rows it holds and
                            // the open slot has somewhere to be.
                            .visible_rows(7)
                            .reorderable(true)
                            .on_select(|_, _, _| {})
                            .on_reorder(|_, _, _| {}),
                        ),
                )
                // The ghost is what the pointer is holding, and the pointer is
                // beside the rows rather than on top of them: staged over a
                // row it would cut the label it is meant to be leaving.
                .children(
                    dnd::staged_ghost(cx)
                        .map(|ghost| div().absolute().left(px(248.0)).top(px(52.0)).child(ghost)),
                ),
        )
        .into_any_element()
}

