                        GraphEdge::new("scene.regions.compare", "scene.regions.score")
                            .ports("out", "in")
                            .label("re-score")
                            .lane(1)
                            .feedback()
                            .active(true),
                    )
                    .on_event(|event, _, cx| {
                        if let NodeGraphEvent::ViewportChanged(viewport) = event {
                            cx.update_global::<SceneCanvasRegions, ()>(|scene, _| {
                                scene.viewport = *viewport;
                            });
                            cx.refresh_windows();
                        }
                    }),
            ),
        )
        .into_any_element()
}

