                        .child(
                            IconView::named(format!("scene.icon.tone.{label}"), Icon::Info, label)
                                .tone(tone)
                                .large(),
                        )
                        .child(
                            div()
                                .row()
                                .gap(px(theme.space(Space::Xs)))
                                .child(IconView::new(Icon::Check).tone(tone))
                                .child(IconView::new(Icon::Danger).tone(tone))
