                [
                    (Icon::ArrowRight, "arrow-right"),
                    (Icon::Return, "return"),
                    (Icon::Copy, "copy"),
                    (Icon::Check, "check"),
                    (Icon::Settings, "settings"),
                ]
                .map(|(glyph, name)| {
                    IconView::named(format!("scene.icon.direction.{name}"), glyph, name)
                        .follow_direction(true)
