    let theme = cx.theme().clone();
    // Spans are the caller's, in byte offsets into each line, and they
    // outrank what the scanner would have found for the same line.
    let lines = [
        CodeLine::new(40, "fn report(&self) -> Outcome {").spans([CodeSpan {
            range: 0..2,
            role: SyntaxColor::Keyword,
        }]),
        CodeLine::new(41, "    let verified = self.check();")
            .spans([CodeSpan {
                range: 4..7,
                role: SyntaxColor::Keyword,
            }])
            .mark(LineMark::Added),
        CodeLine::new(42, "    let stale = self.cached();").mark(LineMark::Removed),
        CodeLine::new(43, "    Outcome::from(verified)").mark(LineMark::Changed),
        CodeLine::new(
            44,
            "    // this line runs off the edge rather than wrapping, because a column carries meaning in code",
        ),
        CodeLine::new(45, "}").mark(LineMark::Error),
    ];
    stack(&theme)
        .w(px(620.0))
        .child(caption(
            &theme,
            "line numbers are the file's, marks are the host's, colour is the caller's",
        ))
        .child(CodeView::new("scene.code.report", lines).language("rust"))
        .child(caption(
            &theme,
            "and where the caller says only what the language is, the four classes it can find",
        ))
        .child(
            CodeView::new(
                "scene.code.scanned",
                [
                    CodeLine::new(1, "def summarize(runs):  # every class in one line"),
                    CodeLine::new(2, "    total = 0"),
                    CodeLine::new(3, "    for run in runs:"),
                    CodeLine::new(4, "        if run.status == \"passed\":"),
                    CodeLine::new(5, "            total += 1"),
                    CodeLine::new(6, "    return total"),
                ],
            )
            .language("python"),
        )
        .child(caption(
            &theme,
            "a language with no table is shown and left plain, never guessed at",
        ))
        .child(
            CodeView::new(
                "scene.code.unknown",
                [
                    CodeLine::new(1, "REPORT SECTION."),
                    CodeLine::new(2, "    MOVE 0 TO TOTAL."),
                ],
            )
            .language("cobol"),
        )
        .into_any_element()
}

fn cascader(window: &mut Window, cx: &mut App) -> AnyElement {
    if !cx.has_global::<SceneCascader>() {
        let cascader = cx.new(|cx| {
            Cascader::new("scene.cascader", window, cx)
                .name("Fixture destination")
                .selected("release-notes")
                .options([
                    CascaderOption::new("guides", "Guides").children([
                        CascaderOption::new("getting-started", "Getting started"),
                        CascaderOption::new("configuration", "Configuration"),
                    ]),
                    CascaderOption::new("reference", "Reference").loading_children(),
                    CascaderOption::new("archive", "Archive").unavailable_children(
                        "The fixture host does not provide archived sections.",
                    ),
                    CascaderOption::new("release-notes", "Release notes"),
                    CascaderOption::new("managed", "Managed section").disabled(true),
                ])
        });
        cascader.update(cx, |cascader, cx| cascader.open(window, cx));
        cx.set_global(SceneCascader { cascader });
    }
    let theme = cx.theme().clone();
    let cascader = cx.global::<SceneCascader>().cascader.clone();
    stack(&theme)
        .w(px(680.0))
        .child(caption(
            &theme,
            "caller-owned hierarchy and value; the open path belongs only to the view",
        ))
        // The trigger is given the width its own popup has, so the scene does
        // not show a control that disagrees with the surface it opens.
        .child(div().w(px(380.0)).child(cascader))
        .into_any_element()
}

fn anchor_list(window: &mut Window, cx: &mut App) -> AnyElement {
    if !cx.has_global::<SceneAnchorList>() {
        let label = cx.strings().text(StringKey::AnchorMoreSections);
        let overflow = cx.new(|cx| Menu::new("scene.anchor-list.menu", window, cx).trigger(label));
        cx.set_global(SceneAnchorList { overflow });
    }
    let theme = cx.theme().clone();
    let overflow = cx.global::<SceneAnchorList>().overflow.clone();
    stack(&theme)
        .w(px(700.0))
        .child(caption(
            &theme,
            "section intents only; the declared overflow moves anchors into a menu",
        ))
        .child(
            AnchorList::new("scene.anchor-list")
                .anchors([
                    Anchor::new("summary", "Summary"),
                    Anchor::new("inputs", "Inputs"),
                    Anchor::new("constraints", "Constraints"),
                    Anchor::new("verification", "Verification"),
                    Anchor::new("history", "History").disabled(true),
                ])
                .active("inputs")
                .overflow_after(3)
                .overflow_menu(overflow)
                .on_navigate(|_, _, _| {}),
        )
        .into_any_element()
}

fn terminal(_window: &mut Window, cx: &mut App) -> AnyElement {
    /// A session's worth of output, chosen so every branch of the painter has
    /// something to paint.
    const SESSION: &[u8] = concat!(
        "\x1b[32m>\x1b[0m cargo run -p xtask -- gate\r\n",
        "\x1b[1mCompiling\x1b[0m gpui-box-kit v0.1.2\r\n",
        "\x1b[2m    dim text stays legible and stays dim\x1b[0m\r\n",
        "\x1b[4munderlined\x1b[0m \x1b[7minverse\x1b[0m \x1b[44;97m on a background \x1b[0m\r\n",
        "\x1b[30m0\x1b[31m1\x1b[32m2\x1b[33m3\x1b[34m4\x1b[35m5\x1b[36m6\x1b[37m7",
        "\x1b[90m8\x1b[91m9\x1b[92ma\x1b[93mb\x1b[94mc\x1b[95md\x1b[96me\x1b[97mf\x1b[0m\r\n",
        "\x1b[38;5;208m256-colour cube\x1b[0m and \x1b[38;2;120;200;255mtruecolour\x1b[0m\r\n",
        "\x1b[32m>\x1b[0m ",
    )
    .as_bytes();

    let theme = cx.theme().clone();
    let panel = |ident: &'static str, state: TerminalState| {
        div()
            .w(px(400.0))
            .h(px(180.0))
            .child(Terminal::new(ident).state(state))
    };

    stack(&theme)
        .child(
            div().w(px(400.0)).h(px(180.0)).child(
                Terminal::new("scene.terminal.ready")
                    .focused(true)
                    .grid(|geometry, _| {
                        let mut emulator = Emulator::new(geometry.cols, geometry.rows);
                        emulator.feed(SESSION);
                        // A selection over the middle of a coloured row, so the
                        // achromatic wash is reviewable against sixteen hues at
                        // once rather than against one.
                        emulator.start_selection(
                            SelectionKind::Drag,
                            emulator.grid_point(4, 0),
                            CellSide::Left,
                        );
                        emulator.update_selection(emulator.grid_point(4, 15), CellSide::Right);
                        Some(GridSnapshot {
                            lines: emulator.lines(),
                            cursor: emulator.cursor(),
                        })
                    })
                    .on_event(|_, _, _| {}),
            ),
        )
        .child(
            row(&theme)
                .items_start()
                .child(panel("scene.terminal.starting", TerminalState::Loading))
                .child(panel(
                    "scene.terminal.unavailable",
                    TerminalState::Unavailable("No shell is configured for this workspace.".into()),
                )),
        )
        .child(
            div().w(px(400.0)).h(px(180.0)).child(
                Terminal::new("scene.terminal.ended")
                    .state(TerminalState::Error("The process exited with status 130.".into()))
                    .grid(|geometry, _| {
                        let mut emulator = Emulator::new(geometry.cols, geometry.rows);
                        emulator.feed(b"\x1b[32m>\x1b[0m tail -f build.log\r\n\x1b[31merror\x1b[0m: interrupted\r\n");
                        Some(GridSnapshot {
                            lines: emulator.lines(),
                            // Nothing is reading this grid any more, so there
                            // is no insertion point in it: a caret drawn under
                            // an exited process invites a keystroke that has
                            // nowhere to go.
                            cursor: None,
                        })
                    }),
            ),
        )
        .into_any_element()
}

fn calendar(window: &mut Window, cx: &mut App) -> AnyElement {
    ensure(window, cx);
    let theme = cx.theme().clone();
    let dates = cx.global::<SceneDates>();
    let (month, unknown) = (dates.month.clone(), dates.unknown.clone());
    stack(&theme)
        .child(
            row(&theme)
                .items_start()
                .gap(px(theme.space(Space::Lg)))
                .child(month)
                .child(unknown),
        )
        .child(
            crate::foundation::text(
                &theme,
                TypeScale::Body,
                "Every weekday name, month name, and blocked reason above came from the \
                     host. The calendar on the right has no today, so it draws no ring and \
                     guesses no month.",
            )
            .max_w(px(560.0))
            .text_tone(&theme, TextTone::Muted),
        )
        .into_any_element()
}

fn date_range(window: &mut Window, cx: &mut App) -> AnyElement {
    ensure(window, cx);
    let theme = cx.theme().clone();
    let dates = cx.global::<SceneDates>();
    let (incomplete, preview, blocked) = (
        dates.incomplete.clone(),
        dates.preview.clone(),
        dates.blocked.clone(),
    );
    // The first two ranges report the same thing, because they are the same
    // range; what differs is that the pointer is over a day in the second, so
    // the caption has to say which picture is which.
    let column = |caption: &'static str, picker: AnyElement| {
        div()
            .column()
            .w(px(320.0))
            .gap(px(theme.space(Space::Xs)))
            .child(
                crate::foundation::text(&theme, TypeScale::Caption, caption)
                    .text_tone(&theme, TextTone::Muted),
            )
            .child(picker)
    };
    stack(&theme)
        .child(
            div()
                .row()
                .items_start()
                .gap(px(theme.space(Space::Lg)))
                .child(column(
                    "a start with no end yet",
                    incomplete.into_any_element(),
                ))
                .child(column(
                    "the same start, previewing the end under the pointer",
                    preview.into_any_element(),
                )),
        )
        // The third picker used to overhang the fixed review frame and looked
        // narrower only because its right edge was clipped. Give every state
        // the same full-width review column instead of squeezing three across.
        .child(column(
            "a finished range with a blocked day inside it",
            blocked.into_any_element(),
        ))
        .into_any_element()
}

fn date_time(window: &mut Window, cx: &mut App) -> AnyElement {
    ensure(window, cx);
    let theme = cx.theme().clone();
    let dates = cx.global::<SceneDates>();
    let (field, refused, clock, twelve) = (
        dates.field.clone(),
        dates.refused.clone(),
        dates.clock.clone(),
        dates.twelve.clone(),
    );
    stack(&theme)
        .child(div().w(px(280.0)).child(field))
        .child(div().w(px(280.0)).child(refused))
        .child(
            row(&theme)
                .gap(px(theme.space(Space::Lg)))
                .child(clock)
                .child(twelve),
        )
        .child(
            crate::foundation::text(
                &theme,
                TypeScale::Body,
                "What the field could not read is still in it, and the refusal is the \
                     adapter's own sentence.",
            )
            .max_w(px(560.0))
            .text_tone(&theme, TextTone::Muted),
        )
        .into_any_element()
}
